package packet;
import core.Diagnostics;
import java.util.ArrayList;import java.util.Collections;import java.util.List;
public final class PcapFile{private final int versionMajor;private final int versionMinor;private final int snapLength;private final int linkType;private final boolean littleEndian;private final List<PcapRecord> records=new ArrayList<>();private final Diagnostics diagnostics;public PcapFile(int versionMajor,int versionMinor,int snapLength,int linkType,boolean littleEndian,Diagnostics diagnostics){this.versionMajor=versionMajor;this.versionMinor=versionMinor;this.snapLength=snapLength;this.linkType=linkType;this.littleEndian=littleEndian;this.diagnostics=diagnostics;}public int versionMajor(){return versionMajor;}public int versionMinor(){return versionMinor;}public int snapLength(){return snapLength;}public int linkType(){return linkType;}public boolean littleEndian(){return littleEndian;}public void add(PcapRecord r){records.add(r);}public List<PcapRecord> records(){return Collections.unmodifiableList(records);}public Diagnostics diagnostics(){return diagnostics;}}
